begin;
create extension if not exists pgtap with schema extensions;
select plan(63);
insert into auth.users(id,email) values
 ('13000000-0000-4000-8000-000000000001','contract-client-a@example.test'),
 ('13000000-0000-4000-8000-000000000002','contract-client-b@example.test'),
 ('13000000-0000-4000-8000-000000000003','contract-manager@example.test'),
 ('13000000-0000-4000-8000-000000000004','contract-staff@example.test'),
 ('13000000-0000-4000-8000-000000000005','contract-manager-b@example.test');
insert into public.service_staff(user_id,display_name) values
 ('13000000-0000-4000-8000-000000000003','Manager A'),
 ('13000000-0000-4000-8000-000000000004','Ordinary staff'),
 ('13000000-0000-4000-8000-000000000005','Manager B');
insert into public.facility_managers(user_id) values('13000000-0000-4000-8000-000000000003'),('13000000-0000-4000-8000-000000000005');
insert into public.sites(id,name) values('13000000-0000-4000-8000-000000000011','A'),('13000000-0000-4000-8000-000000000012','B');
insert into public.site_memberships(site_id,user_id) values('13000000-0000-4000-8000-000000000011','13000000-0000-4000-8000-000000000001'),('13000000-0000-4000-8000-000000000012','13000000-0000-4000-8000-000000000002');
create function pg_temp.sd(n text) returns jsonb language sql as $$select jsonb_build_object('name',n,'address','','customer_name','','contact_name','','contact_email','','contact_phone','','is_archived',false)$$;
create function pg_temp.cd(t text) returns jsonb language sql as $$select jsonb_build_object('number','CP-1','title',t,'customer','Customer A','provider','Service company','starts_on','2026-01-01','ends_on','','state','active','responsible_id','13000000-0000-4000-8000-000000000003','notes','Agreed scope')$$;
create function pg_temp.sv(v uuid,r integer,t text) returns jsonb language sql as $$select public.save_contract_version('13000000-0000-4000-8000-000000000031','13000000-0000-4000-8000-000000000011',v,r,pg_temp.cd(t),'contract.pdf',encode(convert_to('%PDF-1.4 QA %%EOF','UTF8'),'base64'))$$;
set local role anon;
select throws_ok($$select public.can_manage_facilities()$$,'42501',null,'Anonymous cannot check management API');
select throws_ok($$select public.download_contract_file('13000000-0000-4000-8000-000000000041')$$,'42501',null,'Anonymous cannot download');
reset role;
set local role authenticated;
set local request.jwt.claim.sub='13000000-0000-4000-8000-000000000001';
select is(public.can_manage_facilities(),false,'Site membership is not management');
select throws_ok($$insert into public.facility_managers(user_id) values ('13000000-0000-4000-8000-000000000001')$$,'42501',null,'No self-promotion');
select throws_ok($$select public.save_site('13000000-0000-4000-8000-000000000011',1,pg_temp.sd('Hacked'))$$,'42501',null,'Client cannot edit site via RPC');
select throws_ok($$select pg_temp.sv('13000000-0000-4000-8000-000000000041',0,'Hacked')$$,'42501',null,'Client cannot create contract');
select throws_ok($$select public.publish_contract('13000000-0000-4000-8000-000000000031',1,null)$$,'42501',null,'Client cannot publish');
set local request.jwt.claim.sub='13000000-0000-4000-8000-000000000004';
select is(public.can_manage_facilities(),false,'Ordinary active staff cannot manage');
select throws_ok($$select public.save_site('13000000-0000-4000-8000-000000000011',1,pg_temp.sd('Hacked'))$$,'42501',null,'Staff queue admission is insufficient');
set local request.jwt.claim.sub='13000000-0000-4000-8000-000000000003';
select is(public.can_manage_facilities(),true,'Explicit active manager admitted');
select lives_ok($$select public.save_site('13000000-0000-4000-8000-000000000013',0,pg_temp.sd('New site'))$$,'Manager creates site');
select lives_ok($$select public.save_site('13000000-0000-4000-8000-000000000013',0,pg_temp.sd('New site'))$$,'Identical create replay accepted');
select is((select version from public.sites where id='13000000-0000-4000-8000-000000000013'),1,'Create replay does not increment version');
select lives_ok($$select public.save_site('13000000-0000-4000-8000-000000000011',1,pg_temp.sd('Updated A'))$$,'Manager edits site');
select throws_ok($$select public.save_site('13000000-0000-4000-8000-000000000011',1,pg_temp.sd('Stale edit'))$$,'PT409',null,'Stale site edit rejected');
select lives_ok($$select public.save_site('13000000-0000-4000-8000-000000000011',1,pg_temp.sd('Updated A'))$$,'Lost-response same-payload replay accepted');
select is((select version from public.sites where id='13000000-0000-4000-8000-000000000011'),2,'Replay does not create another site version');
select throws_ok($$select public.save_site('13000000-0000-4000-8000-000000000011',2,pg_temp.sd('') )$$,'22023',null,'Blank name rejected in direct RPC');
select lives_ok($$select pg_temp.sv('13000000-0000-4000-8000-000000000041',0,'First title')$$,'Atomic first contract and PDF');
select lives_ok($$select pg_temp.sv('13000000-0000-4000-8000-000000000041',0,'First title')$$,'Same contract operation replay accepted');
select is((select count(*)::int from public.contract_versions),1,'Replay has one version');
select throws_ok($$select pg_temp.sv('13000000-0000-4000-8000-000000000041',0,'Changed payload')$$,'PT409',null,'Operation ID cannot change payload');
select throws_ok($$select pg_temp.sv('13000000-0000-4000-8000-000000000042',0,'Stale')$$,'PT409',null,'Stale contract revision rejected');
select lives_ok($$select pg_temp.sv('13000000-0000-4000-8000-000000000042',1,'Second title')$$,'New snapshot version added');
select results_eq($$select details->>'title' from public.contract_versions order by version$$,$$values('First title'::text),('Second title'::text)$$,'Earlier metadata retained');
select throws_ok($$update public.contract_versions set filename='changed.pdf'$$,'42501',null,'Manager cannot rewrite version rows');
select throws_ok($$delete from private.contract_files$$,'42501',null,'Manager cannot delete immutable file bytes');
select throws_ok($$select public.publish_contract('13000000-0000-4000-8000-000000000031',1,'13000000-0000-4000-8000-000000000041')$$,'PT409',null,'Stale publication rejected');
select throws_ok($$select public.publish_contract('13000000-0000-4000-8000-000000000031',2,'13000000-0000-4000-8000-000000000099')$$,'PT404',null,'Unknown version cannot be published');
set local request.jwt.claim.sub='13000000-0000-4000-8000-000000000001';
select is((select count(*)::int from public.contracts),0,'Unpublished contract hidden even from site member');
select is((select count(*)::int from private.contract_files),0,'Unpublished private file hidden');
set local request.jwt.claim.sub='13000000-0000-4000-8000-000000000003';
select lives_ok($$select public.publish_contract('13000000-0000-4000-8000-000000000031',2,'13000000-0000-4000-8000-000000000041')$$,'Explicit first publication');
select lives_ok($$select public.publish_contract('13000000-0000-4000-8000-000000000031',2,'13000000-0000-4000-8000-000000000041')$$,'Publication replay does not duplicate audit');
select is((select count(*)::int from public.contract_events),3,'Two versions and one publication audited');
set local request.jwt.claim.sub='13000000-0000-4000-8000-000000000001';
select is((select count(*)::int from public.contracts),1,'Published card visible to admitted client');
select results_eq($$select details->>'title' from public.contract_versions$$,$$values('First title'::text)$$,'Client sees selected published snapshot, not latest draft');
select results_eq($$select title from public.contract_summaries('13000000-0000-4000-8000-000000000011')$$,$$values('First title'::text)$$,'Summary does not leak unpublished title');
select is((select count(*)::int from public.download_contract_file('13000000-0000-4000-8000-000000000041')),1,'Published PDF downloadable');
select is((select count(*)::int from public.download_contract_file('13000000-0000-4000-8000-000000000042')),0,'Knowing draft UUID gives no bytes');
select is((select count(*)::int from public.contract_events),0,'Internal management audit not exposed to client');
set local request.jwt.claim.sub='13000000-0000-4000-8000-000000000002';
select is((select count(*)::int from public.contracts),0,'Other site client sees no contract');
select is((select count(*)::int from public.download_contract_file('13000000-0000-4000-8000-000000000041')),0,'Other client cannot use known download UUID');
set local request.jwt.claim.sub='13000000-0000-4000-8000-000000000005';
select lives_ok($$select public.publish_contract('13000000-0000-4000-8000-000000000031',3,'13000000-0000-4000-8000-000000000042')$$,'Another authorized manager can publish second version');
set local request.jwt.claim.sub='13000000-0000-4000-8000-000000000001';
select is((select count(*)::int from public.download_contract_file('13000000-0000-4000-8000-000000000041')),0,'Former version no longer client-downloadable');
select is((select count(*)::int from public.download_contract_file('13000000-0000-4000-8000-000000000042')),1,'Newly selected version available');
reset role;
update public.site_memberships set is_active=false where user_id='13000000-0000-4000-8000-000000000001';
set local role authenticated;
set local request.jwt.claim.sub='13000000-0000-4000-8000-000000000001';
select is((select count(*)::int from public.download_contract_file('13000000-0000-4000-8000-000000000042')),0,'Revoked membership blocks bytes with old claims');
set local request.jwt.claim.sub='13000000-0000-4000-8000-000000000003';
select lives_ok($$select public.publish_contract('13000000-0000-4000-8000-000000000031',4,null)$$,'Publication removed without deleting history');
select is((select count(*)::int from public.contract_versions),2,'Version history retained after unpublish');
select throws_ok($$select public.save_contract_version('13000000-0000-4000-8000-000000000031','13000000-0000-4000-8000-000000000012','13000000-0000-4000-8000-000000000043',5,pg_temp.cd('Moved'),'contract.pdf',encode(convert_to('%PDF-X','UTF8'),'base64'))$$,'PT404',null,'Contract cannot be moved by forging parent ID');
select throws_ok($$select public.save_contract_version(gen_random_uuid(),'13000000-0000-4000-8000-000000000011',gen_random_uuid(),0,pg_temp.cd('Bad'),'../contract.pdf',encode(convert_to('%PDF-X','UTF8'),'base64'))$$,'22023',null,'Path filename rejected');
select throws_ok($$select public.save_contract_version(gen_random_uuid(),'13000000-0000-4000-8000-000000000011',gen_random_uuid(),0,pg_temp.cd('Bad'),'contract.pdf',encode(convert_to('HTML','UTF8'),'base64'))$$,'22023',null,'Non-PDF bytes rejected');
select throws_ok($$select public.save_contract_version(gen_random_uuid(),'13000000-0000-4000-8000-000000000011',gen_random_uuid(),0,pg_temp.cd('Bad'),'contract.pdf',encode(convert_to('%PDF-'||repeat('x',2097152),'UTF8'),'base64'))$$,'22023',null,'Actual decoded size limited');
select throws_ok($$select public.save_contract_version(gen_random_uuid(),'13000000-0000-4000-8000-000000000011',gen_random_uuid(),0,pg_temp.cd('Bad')||'{"ends_on":"2025-01-01"}','contract.pdf',encode(convert_to('%PDF-X','UTF8'),'base64'))$$,'22023',null,'Invalid date period rejected');
select throws_ok($$select public.save_contract_version(gen_random_uuid(),'13000000-0000-4000-8000-000000000011',gen_random_uuid(),0,pg_temp.cd('Bad')||'{"starts_on":"2026-99-99"}','contract.pdf',encode(convert_to('%PDF-X','UTF8'),'base64'))$$,'22008',null,'Invalid calendar date rejected even without end date');
reset role;
update public.facility_managers set is_active=false where user_id='13000000-0000-4000-8000-000000000003';
set local role authenticated;
set local request.jwt.claim.sub='13000000-0000-4000-8000-000000000003';
select is(public.can_manage_facilities(),false,'Management revoke takes effect with unchanged claims');
select throws_ok($$select public.publish_contract('13000000-0000-4000-8000-000000000031',5,'13000000-0000-4000-8000-000000000041')$$,'42501',null,'Revoked manager cannot publish');
reset role;
update public.service_staff set is_active=false where user_id='13000000-0000-4000-8000-000000000005';
set local role authenticated;
set local request.jwt.claim.sub='13000000-0000-4000-8000-000000000005';
select is(public.can_manage_facilities(),false,'Staff deactivation also revokes management');
reset role;
update public.facility_managers set is_active=true where user_id='13000000-0000-4000-8000-000000000003';
update private.maintenance_state set enabled=true where singleton;
set local role authenticated;
set local request.jwt.claim.sub='13000000-0000-4000-8000-000000000003';
select throws_ok($$select public.save_site('13000000-0000-4000-8000-000000000011',2,pg_temp.sd('Maintenance edit'))$$,'PT503',null,'Site RPC cannot bypass maintenance');
select throws_ok($$select pg_temp.sv('13000000-0000-4000-8000-000000000043',5,'Maintenance version')$$,'PT503',null,'Atomic version RPC respects gate');
select throws_ok($$select public.publish_contract('13000000-0000-4000-8000-000000000031',5,'13000000-0000-4000-8000-000000000041')$$,'PT503',null,'Publication RPC respects gate');
reset role;
select throws_ok($$update private.contract_files set pdf=pdf where false$$,'PT503',null,'Private bytes also covered by maintenance');
update private.maintenance_state set enabled=false where singleton;
select is((select count(*)::int from private.contract_files),2,'Failed mutations did not leave partial files');
select is((select count(*)::int from public.contract_versions),2,'Failed mutations did not append versions');
select * from finish();
rollback;
